import{_ as e,o as t,c as i,a5 as r}from"./chunks/framework.C1a7WKBV.js";const _=JSON.parse('{"title":"AI 使用秘籍","description":"从成长路径、项目规则、提示词到进阶功能与省钱技巧，让 AI 编程客户端真正为你所用。","frontmatter":{"title":"AI 使用秘籍","description":"从成长路径、项目规则、提示词到进阶功能与省钱技巧，让 AI 编程客户端真正为你所用。"},"headers":[],"relativePath":"tips/index.md","filePath":"tips/index.md","lastUpdated":1788838685000}'),o={name:"tips/index.md"};function l(n,a,d,p,h,s){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="ai-使用秘籍" tabindex="-1">AI 使用秘籍 <a class="header-anchor" href="#ai-使用秘籍" aria-label="Permalink to &quot;AI 使用秘籍&quot;">​</a></h1><p>接入只是起点。这一板块整理让 AI 编程工具效率翻倍的实战技巧：怎么从零成长为能驾驭 AI 的高手、怎么给 AI 立规矩、怎么把需求说清楚、怎么用上客户端的高阶功能，以及怎么把额度花在刀刃上。</p><h2 id="_1-秘籍目录" tabindex="-1">1. 秘籍目录 <a class="header-anchor" href="#_1-秘籍目录" aria-label="Permalink to &quot;1. 秘籍目录&quot;">​</a></h2><h3 id="_1-1-从零到驾驭-ai-成长路径" tabindex="-1">1.1 从零到驾驭 AI：成长路径 <a class="header-anchor" href="#_1-1-从零到驾驭-ai-成长路径" aria-label="Permalink to &quot;1.1 从零到驾驭 AI：成长路径&quot;">​</a></h3><p>整本手册的总纲。六个阶段的系统训练路径：每个阶段为什么学、具体练什么、怎么算过关、会踩什么坑。不知道从哪开始、学到哪了，先看这篇。</p><p><a href="/tips/roadmap">阅读成长路径 -&gt;</a></p><h3 id="_1-2-通用-ai-编程方法论" tabindex="-1">1.2 通用 AI 编程方法论 <a class="header-anchor" href="#_1-2-通用-ai-编程方法论" aria-label="Permalink to &quot;1.2 通用 AI 编程方法论&quot;">​</a></h3><p>适合所有客户端的基本功：用项目规则文件给 AI 立规矩、管理上下文窗口、把大任务拆成小任务、小步迭代而不是一口气生成。</p><p><a href="/tips/ai-coding-principles">阅读通用方法论 -&gt;</a></p><h3 id="_1-3-prompt-提示词秘籍" tabindex="-1">1.3 Prompt 提示词秘籍 <a class="header-anchor" href="#_1-3-prompt-提示词秘籍" aria-label="Permalink to &quot;1.3 Prompt 提示词秘籍&quot;">​</a></h3><p>需求描述的写法决定生成质量：结构化需求模板、提供约束与示例、让 AI 先出方案再动手、以及审查与修复循环。</p><p><a href="/tips/prompt-secrets">阅读提示词秘籍 -&gt;</a></p><h3 id="_1-4-claude-code-进阶玩法" tabindex="-1">1.4 Claude Code 进阶玩法 <a class="header-anchor" href="#_1-4-claude-code-进阶玩法" aria-label="Permalink to &quot;1.4 Claude Code 进阶玩法&quot;">​</a></h3><p>Plan 模式先想后做、自定义斜杠命令、Hooks 自动化、MCP 扩展工具、子代理并行干活。</p><p><a href="/tips/claude-code-advanced">阅读进阶玩法 -&gt;</a></p><h3 id="_1-5-效率与省钱技巧" tabindex="-1">1.5 效率与省钱技巧 <a class="header-anchor" href="#_1-5-效率与省钱技巧" aria-label="Permalink to &quot;1.5 效率与省钱技巧&quot;">​</a></h3><p>模型分级使用、上下文长度利用、额度分配策略，同样的费用跑出更多的有效产出。</p><p><a href="/tips/token-efficiency">阅读省钱技巧 -&gt;</a></p><h3 id="_1-6-安全与隐私清单" tabindex="-1">1.6 安全与隐私清单 <a class="header-anchor" href="#_1-6-安全与隐私清单" aria-label="Permalink to &quot;1.6 安全与隐私清单&quot;">​</a></h3><p>从数据分级和密钥保护，到 Agent 权限、MCP 工具和交付前审查，建立执行型 AI 的安全边界。</p><p><a href="/tips/security-checklist">阅读安全清单 -&gt;</a></p><h3 id="_1-7-ai-开发与-agent-工程" tabindex="-1">1.7 AI 开发与 Agent 工程 <a class="header-anchor" href="#_1-7-ai-开发与-agent-工程" aria-label="Permalink to &quot;1.7 AI 开发与 Agent 工程&quot;">​</a></h3><p>准备从“使用工具”进入“构建系统”时，学习生产架构、RAG、评测，以及 Agent 的状态机、工具协议、记忆和可观测性。</p><p><a href="/development/">进入 AI 应用开发专题 -&gt;</a> · <a href="/agents/">进入 Agent 工程专题 -&gt;</a></p><h2 id="_2-建议的学习顺序" tabindex="-1">2. 建议的学习顺序 <a class="header-anchor" href="#_2-建议的学习顺序" aria-label="Permalink to &quot;2. 建议的学习顺序&quot;">​</a></h2><ol><li>先读《成长路径》建立全局地图，按阶段推进，不要跳级。</li><li>第一、二阶段的练习直接照做；进入协作阶段后精读《通用 AI 编程方法论》。</li><li>用哪个客户端，就精读哪篇进阶玩法（Claude Code 用户看《Claude Code 进阶玩法》）。</li><li>日常对话中的描述方式，随时对照《Prompt 提示词秘籍》修正。</li><li>最后按自己的额度情况参考《效率与省钱技巧》，并用《安全与隐私清单》检查权限边界。</li><li>要开发自己的 AI 产品，再进入《AI 应用开发》和《Agent 工程》，不要从多 Agent 等复杂架构倒着学。</li></ol>',26)])])}const u=e(o,[["render",l]]);export{_ as __pageData,u as default};
